lemma SplitEq(s: string, cur: string)
  requires NoWS(cur)
  requires AllNoWS(StrSplit(s, " "))
  requires TailNE(StrSplit(s, " "))
  requires |cur| + |StrSplit(s, " ")[0]| > 0
  ensures PySplitWhitespaceAux(s, cur) == [cur + StrSplit(s, " ")[0]] + StrSplit(s, " ")[1..]
  decreases |s|
{
  var r := StrSplit(s, " ");
