    assert r == [s];
    assert s == "";
    assert |cur| > 0;
    assert cur + r[0] == cur;
    assert r[1..] == [];
  } else if s[0] == ' ' {
    SplitSpace(s);
    var r2 := StrSplit(s[1..], " ");
    assert r == [""] + r2;
    assert |cur| > 0;
    assert IsPyWhitespace(s[0]);
    assert AllNoWS(r2) by {
      forall i | 0 <= i < |r2| ensures NoWS(r2[i]) { assert r2[i] == r[i+1]; }
    }
    assert TailNE(r2) by {
      forall i | 1 <= i < |r2| ensures |r2[i]| > 0 { assert r2[i] == r[i+1]; }
    }
    assert |r| >= 2;
    assert r2[0] == r[1];
    assert |r2[0]| > 0;
    SplitEq(s[1..], "");
    assert "" + r2[0] == r2[0];
    assert [r2[0]] + r2[1..] == r2;
    assert PySplitWhitespaceAux(s, cur) == [cur] + PySplitWhitespaceAux(s[1..], "");
    assert cur + r[0] == cur;
    assert r[1..] == r2;
  } else {
    SplitChar(s);
    var r2 := StrSplit(s[1..], " ");
    assert r == [[s[0]] + r2[0]] + r2[1..];
    assert NoWS(r[0]);
    assert r[0][0] == s[0];
    assert !IsPyWhitespace(s[0]);
    var c2 := cur + [s[0]];
    assert NoWS(c2) by {
      forall j | 0 <= j < |c2| ensures !IsPyWhitespace(c2[j]) {
        if j < |cur| { assert c2[j] == cur[j]; } else { assert c2[j] == s[0]; }
      }
    }
    assert AllNoWS(r2) by {
      forall i | 0 <= i < |r2| ensures NoWS(r2[i]) {
        if i == 0 {
          forall j | 0 <= j < |r2[0]| ensures !IsPyWhitespace(r2[0][j]) {
            assert r2[0][j] == r[0][j+1];
          }
        } else {
          assert r2[i] == r[i];
