      }
    }
    assert TailNE(r2) by {
      forall i | 1 <= i < |r2| ensures |r2[i]| > 0 { assert r2[i] == r[i]; }
    }
    SplitEq(s[1..], c2);
    assert c2 + r2[0] == cur + ([s[0]] + r2[0]);
    assert c2 + r2[0] == cur + r[0];
    assert r[1..] == r2[1..];
    assert PySplitWhitespaceAux(s, cur) == PySplitWhitespaceAux(s[1..], c2);
  }
}

