// Python `None` / Optional[T].
datatype Option<T> = None | Some(value: T)

// Helper: a decimal digit character '0'..'9'.
predicate IsDecDigit(c: char)
{
  '0' <= c <= '9'
}

// Helper: value of a decimal digit character.
function DigitValue(c: char): int
  requires IsDecDigit(c)
{
  (c as int) - ('0' as int)
}

// Helper: the character for a decimal digit 0..9.
function DigitChar(d: int): char
  requires 0 <= d <= 9
{
  (('0' as int) + d) as char
}

// Helper: decimal representation of a natural number, with no leading zeros ("0" for 0).
function NatToDecStr(n: nat): string
  decreases n
{
  if n < 10 then [DigitChar(n)]
  else NatToDecStr(n / 10) + [DigitChar(n % 10)]
}

// str: "returns the result of object.__str__() (if defined) or repr(object)."
// For an int, __str__ is its decimal representation, prefixed by '-' when negative.
function PyStrOfInt(n: int): string
{
  if n < 0 then "-" + NatToDecStr(-n) else NatToDecStr(n)
}

// Helper: value of a nonempty all-digit string read in base 10.
function DecDigitsValue(s: string): int
  requires forall i :: 0 <= i < |s| ==> IsDecDigit(s[i])
  decreases |s|
{
  if |s| == 0 then 0
  else DecDigitsValue(s[..|s|-1]) * 10 + DigitValue(s[|s|-1])
}

// int: "x must be a string ... representing an integer literal in the given base.
// The literal can be preceded by '+' or '-' ... The base defaults to 10."
// Models int(s) for base 10. None models the ValueError raised on an invalid literal.
// Modeling assumption: surrounding whitespace and '_' digit separators are not modeled.
function PyIntOfStr(s: string): Option<int>
{
  if |s| > 0 && (s[0] == '+' || s[0] == '-') then
    var body := s[1..];
    if |body| > 0 && (forall i :: 0 <= i < |body| ==> IsDecDigit(body[i])) then
      Some(if s[0] == '-' then -DecDigitsValue(body) else DecDigitsValue(body))
    else None
  else if |s| > 0 && (forall i :: 0 <= i < |s| ==> IsDecDigit(s[i])) then
    Some(DecDigitsValue(s))
  else None
}

// Python `**` on ints with a nonnegative exponent: base multiplied by itself exp times
// (base**0 == 1).
function PyPow(base: int, exp: nat): int
  decreases exp
{
  if exp == 0 then 1 else base * PyPow(base, exp - 1)
}

// Python `//` on ints: floor division, rounding towards -infinity.
// Dividing both operands by -1 leaves the true quotient unchanged; Dafny's Euclidean `/`
// equals floor division when the divisor is positive.
function PyFloorDiv(a: int, b: int): int
  requires b != 0
{
  if b > 0 then a / b else (-a) / (-b)
}

// Python `%` on ints: a == b * (a // b) + a % b, so the result has the sign of the divisor.
function PyMod(a: int, b: int): int
  requires b != 0
{
  a - b * PyFloorDiv(a, b)
}
