// Value of a digit character in Python int() parsing: '0'..'9' -> 0..9,
// 'a'..'z' / 'A'..'Z' -> 10..35; any other char -> 36 (invalid in every base).
function PyCharDigitVal(c: char): int
{
  if '0' <= c <= '9' then (c as int) - ('0' as int)
  else if 'a' <= c <= 'z' then (c as int) - ('a' as int) + 10
  else if 'A' <= c <= 'Z' then (c as int) - ('A' as int) + 10
  else 36
}

predicate AllDigitsInBase(s: string, b: int)
{
  forall i :: 0 <= i < |s| ==> PyCharDigitVal(s[i]) < b
}

function DigitsValueInBase(s: string, b: int): int
  decreases |s|
{
  if |s| == 0 then 0
  else DigitsValueInBase(s[..|s|-1], b) * b + PyCharDigitVal(s[|s|-1])
}

// A nonempty digit string valid in base b, read in base b.
function PyParseDigits(u: string, b: int): Option<int>
{
  if |u| > 0 && AllDigitsInBase(u, b) then Some(DigitsValueInBase(u, b)) else None
}

predicate HasPrefix(t: string, lower: char, upper: char)
{
  |t| >= 2 && t[0] == '0' && (t[1] == lower || t[1] == upper)
}

// Unsigned part of an integer literal for int(s, base).
function PyParseUnsignedBase(t: string, base: int): Option<int>
{
  if base == 0 then
    if HasPrefix(t, 'x', 'X') then PyParseDigits(t[2..], 16)
    else if HasPrefix(t, 'o', 'O') then PyParseDigits(t[2..], 8)
    else if HasPrefix(t, 'b', 'B') then PyParseDigits(t[2..], 2)
    else if |t| > 0 && AllDigitsInBase(t, 10)
            && (t[0] != '0' || forall i :: 0 <= i < |t| ==> t[i] == '0')
      then Some(DigitsValueInBase(t, 10))
    else None
  else if base == 16 && HasPrefix(t, 'x', 'X') then PyParseDigits(t[2..], 16)
  else if base == 8 && HasPrefix(t, 'o', 'O') then PyParseDigits(t[2..], 8)
  else if base == 2 && HasPrefix(t, 'b', 'B') then PyParseDigits(t[2..], 2)
  else PyParseDigits(t, base)
}

// Python int(s, base). None models the ValueError raised for an invalid base
// (not 0 and not in 2..36) or an invalid literal.
// Modeling assumption: surrounding whitespace and '_' separators are not modeled.
function PyIntOfStrBase(s: string, base: int): Option<int>
{
  if !(base == 0 || (2 <= base <= 36)) then None
  else if |s| > 0 && (s[0] == '+' || s[0] == '-') then
    match PyParseUnsignedBase(s[1..], base)
    case None => None
    case Some(v) => Some(if s[0] == '-' then -v else v)
  else PyParseUnsignedBase(s, base)
}
