  requires b != 0
{
  var r := a % b;
  if b > 0 || r == 0 then r else r + b
}

function PyFloorDiv(a: int, b: int): int
  requires b != 0
{
  var q := a / b;
  var r := a % b;
  if b > 0 || r == 0 then q else q - 1
