  (forall i :: 0 <= i < |d| ==> IsDecDigit(d[i]) || d[i] == '_') &&
  (forall i :: 0 <= i < |d| - 1 ==> !(d[i] == '_' && d[i+1] == '_'))
}

// value of a decimal digit string (underscores ignored)
function DecDigitsValue(d: string): int
  decreases |d|
{
  if |d| == 0 then 0
  else if d[|d|-1] == '_' then DecDigitsValue(d[..|d|-1])
  else if IsDecDigit(d[|d|-1]) then DecDigitsValue(d[..|d|-1]) * 10 + ((d[|d|-1] as int) - ('0' as int))
  else DecDigitsValue(d[..|d|-1]) * 10
}

// "x must be a string ... representing an integer literal in the given base.
//  The literal can be preceded by '+' or '-' and be surrounded by whitespace.
//  The base defaults to 10."
predicate IsIntLiteral(x: string)
{
  var t := RStripWs(LStripWs(x));
  |t| > 0 &&
  (if t[0] == '+' || t[0] == '-' then IsDecDigitString(t[1..]) else IsDecDigitString(t))
}

// int(x) for a string x: "Convert a number or string to an integer"
function PyIntOfStr(x: string): int
  requires IsIntLiteral(x)
{
  var t := RStripWs(LStripWs(x));
  if t[0] == '-' then -DecDigitsValue(t[1..])
  else if t[0] == '+' then DecDigitsValue(t[1..])
  else DecDigitsValue(t)
}
