// Length of the maximal run of decimal digits at the start of s
function LeadingDigitsLen(s: string): int
  ensures 0 <= LeadingDigitsLen(s) <= |s|
  ensures |s| > 0 && IsDecDigit(s[0]) ==> LeadingDigitsLen(s) >= 1
  decreases |s|
{
  if |s| > 0 && IsDecDigit(s[0]) then 1 + LeadingDigitsLen(s[1..]) else 0
}

// sum(map(int, re.findall('\d+', s))): re.findall scans left to right and
// returns each maximal non-overlapping run of digits.
function SumOfDigitRuns(s: string): int
  decreases |s|
{
  if |s| == 0 then 0
  else if IsDecDigit(s[0]) then
    var k := LeadingDigitsLen(s);
    DecDigitsValue(s[..k]) + SumOfDigitRuns(s[k..])
  else SumOfDigitRuns(s[1..])
}
