// synth: lemma
lemma SplitJoin(s: string)
  ensures Join(StrSplit(s, " ")) == s
  decreases |s|
{
  if |s| < 1 {
    assert StrSplit(s, " ") == [s];
  } else if s[..1] == " " {
    var R := StrSplit(s[1..], " ");
    SplitJoin(s[1..]);
    var res := [""] + R;
    assert StrSplit(s, " ") == res;
    assert res[1..] == R;
    assert Join(res) == "" + " " + Join(R);
    assert s == s[..1] + s[1..];
  } else {
    var r := StrSplit(s[1..], " ");
    SplitJoin(s[1..]);
    var res := [[s[0]] + r[0]] + r[1..];
    assert StrSplit(s, " ") == res;
    assert s == [s[0]] + s[1..];
    if |r| == 1 {
      assert res == [[s[0]] + r[0]];
      assert Join(r) == r[0];
    } else {
      assert res[1..] == r[1..];
      assert Join(res) == ([s[0]] + r[0]) + " " + Join(r[1..]);
      assert Join(r) == r[0] + " " + Join(r[1..]);
    }
  }
}

